pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 _am) internal {
        uint256 beforeCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeCallerBal = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        vm.assume(beforeCallerBal < minSum);
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint256 afterCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { afterCallerBal = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(!reverted
            && afterCallerBal == beforeCallerBal
            && afterContractBal == beforeContractBal);
    }

    function testFuzz_run(uint256 _am) public {
        _run(_am);
    }

    receive() external payable {}
}
